import json
D={}
for f in ['kt','svl','rel']:
    for it in json.load(open(f+'.json',encoding='utf-8')): D[it['expectedId']]=it
out={}
def touch(i):
    out.setdefault(i,{'id':i}); return out[i]
def rat(i,a,b):
    it=D[i]; assert a in it['rationale'],(i,a[:50]); it['rationale']=it['rationale'].replace(a,b); touch(i)['rationale']=it['rationale']
def stm(i,a,b):
    it=D[i]; assert a in it['requirement'],(i,a[:50]); it['requirement']=it['requirement'].replace(a,b); touch(i)['statement']=it['requirement']
def ac(i,n,new):  # n is 1-based
    it=D[i]; it['acceptanceCriteria'][n-1]=new; touch(i)['acceptanceCriteria']=it['acceptanceCriteria']
def ac_sub(i,n,a,b):
    it=D[i]; s=it['acceptanceCriteria'][n-1]; assert a in s,(i,n,a[:50]); ac(i,n,s.replace(a,b))
def ac_ins(i,after,new):  # insert after 1-based position
    it=D[i]; it['acceptanceCriteria'].insert(after,new); touch(i)['acceptanceCriteria']=it['acceptanceCriteria']
def ac_add(i,new):
    it=D[i]; it['acceptanceCriteria'].append(new); touch(i)['acceptanceCriteria']=it['acceptanceCriteria']
def tadd(i,typ,ref,rel,notes):
    touch(i).setdefault('trace_add',[]).append(dict(type=typ,reference=ref,relation=rel,notes=notes))
def tdel(i,ref):
    touch(i).setdefault('trace_delete',[]).append(ref)

